-- supabase/staging/sql/20261028_s01_propuestas_plataforma_prueba.sql
--
-- SOLO STAGING. Prueba de la 0929 (la liquidación de plataforma se propone sola
-- al leerse), con \i dentro de la transacción y ROLLBACK: staging no cambia. En
-- la empresa A, con Glovo (su 430, la 43000001; su 410, la 41000002) y Norte
-- Centro (su banco, la 57200912), por su camino: entran liquidaciones (el
-- disparador, sin nadie).
--
-- La regla se comparó con la del navegador sobre las 268 liquidaciones de
-- Foodint en producción (la misma entrada a los dos lados): está en el parte.
-- Aquí, sus caminos:
--   0. Los 16 casos de las pruebas del navegador que se borran: lo mismo.
--   1. Entra una del CSV: se propone sola (comisión y cargos con su IVA,
--      compensados con lo que te debe), propuesta y sin validar.
--   2. Entra una del correo sin su factura de comisión: no se propone y se
--      dice; llega su factura: se propone sola, solo la compensación.
--   3. Con lo aprendido (regla 11): la cuenta corregida, y dicho.
--   4. Entra una de referencia: no se asienta, y se dice por qué.
--   5. Si proponer falla al leerla, la liquidación entra igual y queda dicho.
--   6. Alguien sin cuenta no puede proponer.
--   7. La vuelta atrás: no queda nada de la 0929.
--
-- Nombra lo que toca, para el analizador: _conta_plataforma_regla,
-- _conta_plataforma_entrada, conta_propuestas_plataforma,
-- _conta_proponer_plataforma, conta_proponer_plataformas,
-- tg_conta_plataforma_proponer, conta_aprendizaje, channel_settlement, journal_correction,
-- conta_propuesta_pendiente, journal_entry, journal_line.

\set ON_ERROR_STOP 1
begin;
do $$ begin
  if exists (select 1 from public.accounts where id in ('51ad1792-6629-4ef7-833a-b57b09a86710', '00000000-0000-0000-0000-000000000001')) then
    raise exception 'PRUEBA S01 PLATAFORMA: esta base tiene cuentas de producción. No se toca nada.';
  end if;
end $$;
set local statement_timeout = '180s';
set local lock_timeout = '120s';
lock table public.accounts, public.company, public.company_account, public.bank_match in share row exclusive mode;
lock table public.conta_enlace_pago, public.treasury_account, public.journal_entry in access exclusive mode;

select to_regclass('public.conta_propuesta_pendiente') is not null as ya_esta_la_0753,
       to_regprocedure('public.conta_propuestas_socio(uuid,uuid)') is not null as ya_esta_la_0905,
       to_regprocedure('public.conta_propuestas_plataforma(uuid,uuid)') is not null as ya_esta_la_0929 \gset
\if :ya_esta_la_0753
\else
\i supabase/migrations/20261028T0753_s01_propuestas_solas_base.sql
\endif
\if :ya_esta_la_0905
\else
\i supabase/migrations/20261028T0905_s01_propuestas_socio.sql
\endif
\if :ya_esta_la_0929
\else
\i supabase/migrations/20261028T0929_s01_propuestas_plataforma.sql
\endif

create or replace function pg_temp.lineas(p uuid) returns text language sql as $$
  select string_agg(ca.code || ' ' || coalesce(jl.debit, 0)::numeric(14,2) || '/' || coalesce(jl.credit, 0)::numeric(14,2), ' · ' order by jl.position)
    from public.journal_line jl join public.company_account ca on ca.id = jl.company_account_id where jl.entry_id = p
$$;
create or replace function pg_temp.asiento(p_liq uuid) returns public.journal_entry language sql as $$
  select * from public.journal_entry where company_id = '3b34403a-a7d6-4a48-a8d7-737e8cababdc' and source_type = 'channel_settlement' and source_id = p_liq
$$;
create temp table _p (clave text primary key, v text) on commit drop;
grant select, insert, update on _p to authenticated, anon, service_role;
insert into _p values ('empresa', '3b34403a-a7d6-4a48-a8d7-737e8cababdc'), ('cuenta', 'c01a0000-0000-4000-8000-00000000000a'),
  ('admin', 'c01a0000-0000-4000-8000-0000000000a1'), ('glovo', 'e0200000-0000-4000-8000-00000000a0c1'), ('centro', 'c01a0000-0000-4000-8000-0000000000a2');

do $$
declare e uuid := (select v::uuid from _p where clave = 'empresa');
begin
  if not public.conta_dia_abierto(e, '2026-10-20') then raise exception 'PRUEBA S01 PLATAFORMA · siembra: el 20/10 no está abierto.'; end if;
  -- Lo aprendido cambia las cuentas que se esperan: sin correcciones previas.
  -- (Los asientos de otras liquidaciones dan igual: cada paso mira los de las
  -- suyas, por source_id. Staging tiene uno propuesto del 07/10.)
  if exists (select 1 from public.journal_correction where company_id = e and origin_key like 'channel_settlement:%') then
    raise exception 'PRUEBA S01 PLATAFORMA · siembra: ya hay correcciones aprendidas de liquidaciones de plataforma.';
  end if;
  raise notice 'siembra: % asiento(s) de liquidación de plataforma de antes en la empresa A, que la prueba no mira',
    (select count(*) from public.journal_entry where company_id = e and source_type = 'channel_settlement');
end $$;

