create or replace function pg_temp.junta(r jsonb) returns jsonb language sql as $$
  select case when r ? 'sin_propuesta' then r else jsonb_build_object('entrada', (r->'propuesta'->'entrada') || jsonb_build_object('razones', (r->'propuesta'->'entrada'->'razones')
    || coalesce((select jsonb_agg(jsonb_build_object('decision', 'Mira esto', 'porque', a #>> '{}') order by o) from jsonb_array_elements(r->'avisos') with ordinality z(a, o)), '[]'::jsonb)),
    'lineas', r->'propuesta'->'lineas') end
$$;
do $$
declare v_mal text;
begin
  select string_agg(n::text, ', ' order by n) into v_mal from _casos where pg_temp.junta(public._conta_plataforma_regla(e, c)) is distinct from esperado;
  if v_mal is not null then raise exception 'PRUEBA S01 PLATAFORMA · 0: los casos % no dan lo del navegador.', v_mal; end if;
  raise notice '0 · los 16 casos de las pruebas del navegador: la regla de SQL da lo mismo';
end $$;

-- ── 1 · Entra una del CSV: se propone sola ─────────────────────────────────
insert into public.channel_settlement (id, account_id, channel_id, location_id, settlement_ref, settlement_date, period_from, period_to, flow_type, source, import_key,
                                       gross_sales, commission, delivery_transport, net_payout)
values ('5e010000-0000-4000-8000-000000000001', (select v::uuid from _p where clave = 'cuenta'), (select v::uuid from _p where clave = 'glovo'), (select v::uuid from _p where clave = 'centro'),
        'S01-P1', '2026-10-20', '2026-10-12', '2026-10-18', 'own', 'import_csv_uber', 'prueba-s01-plataforma-1', 200, -20, -5, 169.75);
do $$
declare je public.journal_entry := pg_temp.asiento('5e010000-0000-4000-8000-000000000001');
begin
  if je.id is null or je.status <> 'propuesto' or je.entry_date <> '2026-10-20' or je.concept <> 'Liquidación Glovo · S01-P1' then
    raise exception 'PRUEBA S01 PLATAFORMA · 1: al entrar no se propuso sola (%, %).', je.status,
      (select porque from public.conta_propuesta_pendiente where origen_id = '5e010000-0000-4000-8000-000000000001');
  end if;
  if pg_temp.lineas(je.id) <> '62300000 20.00/0.00 · 62900000 5.00/0.00 · 47200021 5.25/0.00 · 41000002 0.00/30.25 · 41000002 30.25/0.00 · 43000001 0.00/30.25' then
    raise exception 'PRUEBA S01 PLATAFORMA · 1: las líneas fueron «%».', pg_temp.lineas(je.id);
  end if;
  raise notice '1 · la del CSV, propuesta sola: %', pg_temp.lineas(je.id);
end $$;

-- ── 2 · La del correo, sin su factura y después con ella ──────────────────
insert into public.channel_settlement (id, account_id, channel_id, location_id, settlement_ref, settlement_date, period_from, period_to, flow_type, source, import_key,
                                       gross_sales, commission, net_payout, raw)
values ('5e010000-0000-4000-8000-000000000002', (select v::uuid from _p where clave = 'cuenta'), (select v::uuid from _p where clave = 'glovo'), (select v::uuid from _p where clave = 'centro'),
        'S01-P2', '2026-10-20', '2026-10-12', '2026-10-18', 'own', 'correo_uber', 'prueba-s01-plataforma-2', 100, -10, 87.90, '{"factura": {"total": 12.10}}');
do $$
declare e uuid := (select v::uuid from _p where clave = 'empresa');
begin
  if (pg_temp.asiento('5e010000-0000-4000-8000-000000000002')).id is not null then
    raise exception 'PRUEBA S01 PLATAFORMA · 2: sin su factura de comisión se propuso.';
  end if;
  if (select porque || ' · ' || donde from public.conta_propuesta_pendiente where company_id = e and origen = 'channel_settlement' and origen_id = '5e010000-0000-4000-8000-000000000002')
     is distinct from 'Falta su factura de comisión (la liquidación la propone al leerse): sin ella, la comisión no se asienta aquí. · Ventas › Liquidaciones' then
    raise exception 'PRUEBA S01 PLATAFORMA · 2: el «no he podido» es «%».',
      (select porque from public.conta_propuesta_pendiente where company_id = e and origen_id = '5e010000-0000-4000-8000-000000000002');
  end if;
end $$;
update public.channel_settlement set commission_invoice_id = (select si.id from public.supplier_invoice si where si.account_id = (select v::uuid from _p where clave = 'cuenta')
                                                                and si.invoice_number is not null order by si.id limit 1)
 where id = '5e010000-0000-4000-8000-000000000002';
do $$
declare e uuid := (select v::uuid from _p where clave = 'empresa'); je public.journal_entry := pg_temp.asiento('5e010000-0000-4000-8000-000000000002');
begin
  if je.id is null or pg_temp.lineas(je.id) <> '41000002 12.10/0.00 · 43000001 0.00/12.10' then
    raise exception 'PRUEBA S01 PLATAFORMA · 2: con su factura, «%».', pg_temp.lineas(je.id);
  end if;
  if exists (select 1 from public.conta_propuesta_pendiente where company_id = e and origen_id = '5e010000-0000-4000-8000-000000000002') then
    raise exception 'PRUEBA S01 PLATAFORMA · 2: el «no he podido» sigue ahí.';
  end if;
  raise notice '2 · la del correo: sin su factura, dicho; con ella, propuesta sola (%)', pg_temp.lineas(je.id);
end $$;

-- ── 3 · Con lo aprendido (regla 11) ────────────────────────────────────────
