values ((select v::uuid from _p where clave = 'cuenta'), (select v::uuid from _p where clave = 'empresa'), 'channel_settlement:' || (select v from _p where clave = 'glovo'),
        '62300000', '62700000', 'Julio', '2026-10-01 10:00:00+00');
insert into public.channel_settlement (id, account_id, channel_id, location_id, settlement_ref, settlement_date, period_from, period_to, flow_type, source, import_key,
                                       gross_sales, commission, net_payout)
values ('5e010000-0000-4000-8000-000000000003', (select v::uuid from _p where clave = 'cuenta'), (select v::uuid from _p where clave = 'glovo'), (select v::uuid from _p where clave = 'centro'),
        'S01-P3', '2026-10-20', '2026-10-12', '2026-10-18', 'own', 'import_csv_uber', 'prueba-s01-plataforma-3', 100, -100, -21);
do $$
declare je public.journal_entry := pg_temp.asiento('5e010000-0000-4000-8000-000000000003');
begin
  if je.id is null or pg_temp.lineas(je.id) not like '62700000 100.00/0.00 · %'
     or not exists (select 1 from jsonb_array_elements(je.reasons) r where r->>'decision' = 'Lo has corregido antes'
                      and r->>'porque' = 'en la anterior del mismo origen cambiaste 62300000 por 62700000 (Julio): lo hago igual') then
    raise exception 'PRUEBA S01 PLATAFORMA · 3: con lo aprendido, «%» (%).', pg_temp.lineas(je.id), je.reasons;
  end if;
  raise notice '3 · con lo aprendido: % y dicho', pg_temp.lineas(je.id);
end $$;
-- Lo mismo para las facturas del navegador (conta_aprendizaje), como el administrador.
select set_config('request.jwt.claims', json_build_object('sub', (select v from _p where clave = 'admin'), 'role', 'authenticated')::text, true);
set local role authenticated;
do $$
declare x jsonb := public.conta_aprendizaje((select v::uuid from _p where clave = 'empresa'), 'channel_settlement:' || (select v from _p where clave = 'glovo'), array['62300000', '47200021']);
begin
  if x->'cuentas' <> '["62700000", "47200021"]'::jsonb or x->'razon'->>'decision' <> 'Lo has corregido antes' then
    raise exception 'PRUEBA S01 PLATAFORMA · 3: conta_aprendizaje dio %.', x;
  end if;
  raise notice '3 · y conta_aprendizaje (las facturas del navegador): %', x->'cuentas';
end $$;
reset role;

