        'S01-P4', '2026-10-20', 'own', 'import_csv_uber', 'prueba-s01-plataforma-4', 100, -10, true);
do $$ begin
  if (pg_temp.asiento('5e010000-0000-4000-8000-000000000004')).id is not null
     or (select porque from public.conta_propuesta_pendiente where origen_id = '5e010000-0000-4000-8000-000000000004')
        is distinct from 'De referencia: es de antes del cierre de la contabilidad; no lleva factura ni asiento.' then
    raise exception 'PRUEBA S01 PLATAFORMA · 4: la de referencia no se trató como tal.';
  end if;
  raise notice '4 · la de referencia: sin asiento, y dicho por qué';
end $$;

