savepoint falla;
create or replace function public._conta_proponer_plataforma(p_company uuid, p_liq uuid, p_quien text)
returns jsonb language plpgsql as $$ begin raise exception 'fallo simulado de la prueba'; end $$;
insert into public.channel_settlement (id, account_id, channel_id, location_id, settlement_ref, settlement_date, flow_type, source, import_key, gross_sales, commission)
values ('5e010000-0000-4000-8000-000000000005', (select v::uuid from _p where clave = 'cuenta'), (select v::uuid from _p where clave = 'glovo'), (select v::uuid from _p where clave = 'centro'),
        'S01-P5', '2026-10-20', 'own', 'import_csv_uber', 'prueba-s01-plataforma-5', 50, -5);
do $$ begin
  if not exists (select 1 from public.channel_settlement where id = '5e010000-0000-4000-8000-000000000005')
     or (select porque from public.conta_propuesta_pendiente where origen_id = '5e010000-0000-4000-8000-000000000005' and company_id = (select v::uuid from _p where clave = 'empresa'))
        is distinct from 'No he podido proponerla al leerla: fallo simulado de la prueba' then
    raise exception 'PRUEBA S01 PLATAFORMA · 5: con el fallo, la liquidación no entró o no quedó dicho.';
  end if;
  raise notice '5 · si proponer falla, la liquidación entra igual y queda dicho';
end $$;
rollback to savepoint falla;

-- ── 6 · Sin cuenta, no ──────────────────────────────────────────────────────
select set_config('request.jwt.claims', json_build_object('role', 'anon')::text, true);
set local role anon;
do $$
declare v_err text;
begin
  begin perform public.conta_proponer_plataformas((select v::uuid from _p where clave = 'empresa'), '2026-10-01', '2026-10-31', 'Nadie');
  exception when others then v_err := sqlerrm; end;
  if v_err is null then raise exception 'PRUEBA S01 PLATAFORMA · 6: alguien sin cuenta propone.'; end if;
  raise notice '6 · sin cuenta, no se propone («%»)', v_err;
end $$;
reset role;

